+	uint32_t pf_size = 32;
+	stream_buffer->put_32(pf_size);
+
+	uint32_t pf_flags = info.compressed ? DDPF_FOURCC : DDPF_RGB;
+	stream_buffer->put_32(pf_flags);
+
+	uint32_t fourcc = _image_format_to_fourcc_format(image->get_format());

